import java.util.*;

class Solution {
    public int ladderLength(String begin, String end, String[] words) {
        Set<String> left = new HashSet<>(Arrays.asList(words));
        if (!left.contains(end)) return 0;
        ArrayDeque<String> q = new ArrayDeque<>();
        q.add(begin);
        left.remove(begin);
        int level = 1; // words in the chain so far
        while (!q.isEmpty()) {
            for (int s = q.size(); s > 0; s--) {
                char[] w = q.poll().toCharArray();
                for (int i = 0; i < w.length; i++) {
                    char orig = w[i];
                    for (char ch = 'a'; ch <= 'z'; ch++) {
                        if (ch == orig) continue;
                        w[i] = ch;
                        String next = new String(w);
                        if (next.equals(end)) return level + 1;
                        if (left.remove(next)) q.add(next); // remove = mark visited
                    }
                    w[i] = orig;
                }
            }
            level++;
        }
        return 0;
    }
}

