function ladderLength(begin, end, words) {
  const ws = new Set(words); if (!ws.has(end)) return 0;
  const q = [[begin, 1]], seen = new Set([begin]);
  for (let h = 0; h < q.length; h++) {
    const [w, d] = q[h]; if (w === end) return d;
    for (let i = 0; i < w.length; i++) for (let c = 97; c < 123; c++) {
      const nw = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
      if (ws.has(nw) && !seen.has(nw)) { seen.add(nw); q.push([nw, d + 1]); }
    }
  }
  return 0;
}
